                        AdjustShuttlePlaceOrder(0);
                        iWhichShuttle=InArmSuck.iWhichSht;
                    }
                    InArmSuck.iWhichSht=iWhichShuttle;
                    InArmSuck.iWhichKit=iInArmiWhichKit;
